/**
 * Layer 1 / 3d — Autonomous Failure Report Generator
 * Auto-generated by the autonomous QE framework.
 *
 * Runs the full autonomous QA cycle against an auto-mocked schema, then:
 *   1. Categorizes every anomaly into one of six failure classes.
 *   2. Produces a machine-readable JSON report (qa-failure-report.json) for
 *      CI artifact upload and dashboard consumption.
 *   3. Generates a human-readable HEALING_REPORT.md per run.
 *
 * Failure categories:
 *   schema_drift     — field renamed / removed in schema.graphql
 *   resolver_bug     — data mismatch from resolver logic
 *   upstream_change  — REST API shape changed (stub mismatch)
 *   parse_layer      — null propagation in parse-service.ts
 *   auth_failure     — auth check rejected or missing token
 *   performance      — query exceeded 1 500 ms threshold
 */

import { readFileSync, existsSync, writeFileSync } from 'fs';
import { join } from 'path';
import { addMocksToSchema } from '@graphql-tools/mock';
import { buildSubgraphSchema } from '@apollo/subgraph';
import { mockCustomScalars } from '@apollo/graphql-testing-library';
import gql from 'graphql-tag';

import { runAutonomousQA } from '../../qa/runner';
import type { CoverageFailure } from '../../qa/agents/coverage-agent';

// ── types ─────────────────────────────────────────────────────────────────────

type FailureCategory =
  | 'schema_drift'
  | 'resolver_bug'
  | 'upstream_change'
  | 'parse_layer'
  | 'auth_failure'
  | 'performance';

interface CategorizedFailure {
  /** The query string or field identifier that failed. */
  test: string;
  category: FailureCategory;
  /** Source file most likely responsible for the failure. */
  file: string;
  /** One-sentence machine-generated diagnosis. */
  diagnosis: string;
  /** Suggested code fix. */
  suggestedFix: string;
}

interface FailureReport {
  runId: string;
  timestamp: string;
  totalQueries: number;
  totalAnomalies: number;
  failures: CategorizedFailure[];
}

// ── failure categorizer ───────────────────────────────────────────────────────

function categorizeFailure(failure: CoverageFailure): CategorizedFailure {
  const reason = failure.reason ?? '';

  // Default to resolver_bug; narrow by heuristic pattern matching.
  let category: FailureCategory = 'resolver_bug';
  let file = 'src/resolvers/';
  let diagnosis = reason || 'Unexpected error returned from resolver';
  let suggestedFix =
    'Inspect resolver and compare output against upstream REST response shape';

  if (reason.includes('LATENCY_THRESHOLD_EXCEEDED')) {
    category = 'performance';
    file = 'src/resolvers/';
    diagnosis =
      'Query exceeded 1 500 ms threshold — likely unbounded upstream call or missing DataLoader';
    suggestedFix =
      'Add DataLoader batching or increase Apollo response-cache TTL (currently 86 400 s)';
  } else if (
    /cannot read prop/i.test(reason) ||
    /undefined/i.test(reason)
  ) {
    category = 'parse_layer';
    file = 'src/parse-service.ts';
    diagnosis =
      'Null propagation in parse function — REST field may have been renamed or removed';
    suggestedFix = 'Add null guard: `field: raw?.field ?? null`';
  } else if (
    /not found/i.test(reason) ||
    /field.*missing/i.test(reason)
  ) {
    category = 'schema_drift';
    file = 'schema.graphql';
    diagnosis =
      'Schema field present in test but absent from schema — likely removed from SDL';
    suggestedFix =
      'Run `npm run codegen` and update affected test assertions; then re-run `--updateSnapshot`';
  } else if (
    /unauthori[zs]ed/i.test(reason) ||
    /\bauth\b/i.test(reason)
  ) {
    category = 'auth_failure';
    file = 'src/graphql/security/validationRules.ts';
    diagnosis =
      'Auth check failed — missing or expired token in request context';
    suggestedFix =
      'Verify context.dataSources carries a valid auth token before forwarding to resolver';
  } else if (
    /\bfetch\b/i.test(reason) ||
    /\bnetwork\b/i.test(reason) ||
    /upstream/i.test(reason)
  ) {
    category = 'upstream_change';
    file = 'src/api.ts';
    diagnosis =
      'Upstream REST API shape changed — field missing or renamed in remote response';
    suggestedFix = 'Update API method stub and regenerate resolver types with `npm run codegen`';
  }

  return { test: failure.field, category, file, diagnosis, suggestedFix };
}

// ── healing report markdown helper ───────────────────────────────────────────

function buildHealingReport(report: FailureReport): string {
  const lines: string[] = [
    `# HEALING_REPORT — ${report.runId}`,
    ``,
    `**Timestamp:** ${report.timestamp}`,
    `**Total queries executed:** ${report.totalQueries}`,
    `**Total anomalies detected:** ${report.totalAnomalies}`,
    ``,
  ];

  if (report.failures.length === 0) {
    lines.push('> All resolvers passed — no healing required.');
    return lines.join('\n');
  }

  lines.push('## Failures');
  lines.push('');
  lines.push('| # | Category | File | Diagnosis | Suggested Fix |');
  lines.push('|---|----------|------|-----------|---------------|');

  report.failures.forEach((f, i) => {
    lines.push(
      `| ${i + 1} | \`${f.category}\` | \`${f.file}\` | ${f.diagnosis} | ${f.suggestedFix} |`,
    );
  });

  lines.push('');
  lines.push(
    '> Auto-generated by `src/__tests__/generated/failure.report.test.ts`. ' +
    'Schema-drift entries can be resolved by running `npm run codegen` followed by `--updateSnapshot`.',
  );

  return lines.join('\n');
}

// ── schema setup ──────────────────────────────────────────────────────────────

const typeDefs = gql(readFileSync('schema.graphql', 'utf-8'));
const federationSchema = buildSubgraphSchema({ typeDefs, resolvers: {} });
const autoMockedSchema = addMocksToSchema({
  schema: federationSchema,
  mocks: mockCustomScalars(federationSchema),
});

// ── suite ─────────────────────────────────────────────────────────────────────

describe('Generated Failure Report: Autonomous QA', () => {
  let report: FailureReport;

  beforeAll(async () => {
    const metrics = await runAutonomousQA({ schema: autoMockedSchema });

    const failures = metrics.anomalies.map(categorizeFailure);

    report = {
      runId: `qa-${Date.now()}`,
      timestamp: new Date().toISOString(),
      totalQueries: metrics.totalQueriesExecuted,
      totalAnomalies: metrics.totalAnomaliesDetected,
      failures,
    };

    // Persist machine-readable report for CI artifact upload.
    writeFileSync(
      join(process.cwd(), 'qa-failure-report.json'),
      JSON.stringify(report, null, 2),
    );

    // Persist human-readable healing report.
    writeFileSync(
      join(process.cwd(), 'HEALING_REPORT.md'),
      buildHealingReport(report),
    );
  }, 60_000);

  // ── structural assertions ─────────────────────────────────────────────────

  it('produces a valid machine-readable failure report', () => {
    expect(report).toMatchObject({
      runId:          expect.stringMatching(/^qa-\d+$/),
      timestamp:      expect.stringMatching(/^\d{4}-\d{2}-\d{2}T/),
      totalQueries:   expect.any(Number),
      totalAnomalies: expect.any(Number),
      failures:       expect.any(Array),
    });
    expect(report.totalQueries).toBeGreaterThan(0);
  });

  it('every categorized failure has a valid category, diagnosis, and fix', () => {
    const validCategories = new Set<FailureCategory>([
      'schema_drift',
      'resolver_bug',
      'upstream_change',
      'parse_layer',
      'auth_failure',
      'performance',
    ]);

    for (const f of report.failures) {
      expect(validCategories.has(f.category)).toBe(true);
      expect(typeof f.diagnosis).toBe('string');
      expect(f.diagnosis.length).toBeGreaterThan(0);
      expect(typeof f.suggestedFix).toBe('string');
      expect(f.suggestedFix.length).toBeGreaterThan(0);
    }
  });

  it('qa-failure-report.json was written to disk', () => {
    expect(existsSync(join(process.cwd(), 'qa-failure-report.json'))).toBe(true);
    const raw = JSON.parse(readFileSync(join(process.cwd(), 'qa-failure-report.json'), 'utf-8'));
    expect(raw.runId).toBeTruthy();
    expect(Array.isArray(raw.failures)).toBe(true);
  });

  it('HEALING_REPORT.md was written to disk', () => {
    expect(existsSync(join(process.cwd(), 'HEALING_REPORT.md'))).toBe(true);
    const content = readFileSync(join(process.cwd(), 'HEALING_REPORT.md'), 'utf-8');
    expect(content).toMatch(/^# HEALING_REPORT/);
  });

  it('no HIGH-severity anomalies detected against auto-mocked schema', () => {
    // Performance-category failures are acceptable; resolver errors are not.
    const nonPerf = report.failures.filter((f) => f.category !== 'performance');
    expect(nonPerf).toHaveLength(0);
  });

  it('generates at least one query per domain resolver', () => {
    // The QA runner must exercise every resolver in Query.* — a zero count
    // means query generation is broken, not that the schema is clean.
    expect(report.totalQueries).toBeGreaterThan(10);
  });
});
